"use client"

import Link from "next/link"
import { useEffect, useMemo, useRef, useState } from "react"
import {
  Activity, AlertTriangle, ArrowRight, Briefcase, Building, Calculator, CheckCircle,
  ChevronRight, Clock, DollarSign, Eye, FileText, Handshake, History, Layers, MessageSquare,
  Percent, Plus, RefreshCw, Save, Scale, Search, Send, ShieldCheck, TrendingUp, UserCheck, Users, X,
} from "lucide-react"
import styles from "./RevenueProposalWorkspace.module.css"
import { PROPOSAL_NAVIGATION, PROPOSAL_ROUTE_CONTRACTS } from "./route-contracts"
import type { ProposalContextType, ProposalExperienceKey, ProposalModalKind, ProposalRecord } from "./types"
import { proposalMutation, useProposalPortfolio } from "./useProposalPortfolio"

const money = new Intl.NumberFormat("fr-FR", { maximumFractionDigits: 0 })
const decimal = new Intl.NumberFormat("fr-FR", { maximumFractionDigits: 1 })
const dateFmt = new Intl.DateTimeFormat("fr-FR", { dateStyle: "medium" })

function dh(value: unknown) { const n=Number(value||0); return `${money.format(Number.isFinite(n)?n:0)} Dh` }
function pct(value: unknown) { const n=Number(value||0); return `${decimal.format(Number.isFinite(n)?n:0)} %` }
function date(value: unknown) { if(!value)return "—"; const d=new Date(String(value)); return Number.isNaN(d.getTime())?"—":dateFmt.format(d) }
function statusClass(status?:string|null){
  const value=String(status||"").toLowerCase()
  if(["accepted","approved","contract_ready","sent","completed"].includes(value))return `${styles.status} ${styles.statusGreen}`
  if(["rejected","withdrawn","expired","lost","blocked"].includes(value))return `${styles.status} ${styles.statusRed}`
  if(["approval_required","pricing_review","revision_requested","counteroffer_received"].includes(value))return `${styles.status} ${styles.statusAmber}`
  if(["negotiation","open","customer_review"].includes(value))return `${styles.status} ${styles.statusViolet}`
  return styles.status
}
function statusLabel(status?:string|null){return String(status||"draft").replaceAll("_"," ")}

type Props={ experience:ProposalExperienceKey; contextId?:string|null; contextType?:ProposalContextType }

