  "create-proposal":{title:"Créer une proposition gouvernée",subtitle:"Reliez l’offre à son contexte, sa valeur et son responsable.",endpoint:"/api/revenue-command-center/proposal/proposals"},
  "select-opportunity":{title:"Relier l’opportunité",subtitle:"Sélectionnez la source commerciale autoritative de la proposition.",endpoint:"/api/revenue-command-center/proposal/commands"},
  "add-line":{title:"Ajouter une ligne de service",subtitle:"Définissez portée, quantité, prix, coût et caractère optionnel.",endpoint:"/api/revenue-command-center/proposal/lines"},
  "edit-line":{title:"Modifier une ligne de service",subtitle:"Corrigez uniquement le brouillon actif; les versions figées restent immuables.",endpoint:"/api/revenue-command-center/proposal/commands"},
  "optional-line":{title:"Ajouter une option commerciale",subtitle:"Séparez clairement l’option de la portée ferme proposée.",endpoint:"/api/revenue-command-center/proposal/commands"},
  "add-term":{title:"Ajouter une condition commerciale",subtitle:"Formalisez une condition visible client sans exposer les notes internes.",endpoint:"/api/revenue-command-center/proposal/commands"},
  "pricing-scenario":{title:"Créer un scénario tarifaire",subtitle:"Modélisez la valeur, la remise et la marge avant décision.",endpoint:"/api/revenue-command-center/proposal/pricing"},
  discount:{title:"Demander une remise",subtitle:"Toute remise doit être justifiée, mesurée et approuvée selon l’autorité.",endpoint:"/api/revenue-command-center/proposal/discounts"},
  "pricing-approval":{title:"Demander l’approbation tarifaire",subtitle:"Soumettez prix, remise et marge à l’autorité compétente.",endpoint:"/api/revenue-command-center/proposal/commands"},
  "margin-exception":{title:"Demander une exception de marge",subtitle:"Exposez la conséquence financière et le motif commercial.",endpoint:"/api/revenue-command-center/proposal/margin-exceptions"},
  "approve-proposal":{title:"Approuver la proposition",subtitle:"Autorisez la version et la position financière exactes.",endpoint:"/api/revenue-command-center/proposal/commands"},
  "reject-proposal":{title:"Rejeter la proposition",subtitle:"Documentez la raison et la correction attendue.",endpoint:"/api/revenue-command-center/proposal/commands"},
  "return-correction":{title:"Retourner pour correction",subtitle:"Définissez les corrections exigées avant une nouvelle soumission.",endpoint:"/api/revenue-command-center/proposal/commands"},
  version:{title:"Créer une version immuable",subtitle:"Figez le contenu, la tarification et les conditions exactes de cette offre.",endpoint:"/api/revenue-command-center/proposal/versions"},
  "compare-versions":{title:"Comparer deux versions",subtitle:"Inspectez les variations de portée, prix, marge et conditions.",endpoint:"",mode:"view"},
  "generate-preview":{title:"Aperçu client contrôlé",subtitle:"Visualisez la version destinataire sans coûts ni notes internes.",endpoint:"",mode:"view"},
  "generate-document":{title:"Générer le snapshot documentaire",subtitle:"Enregistrez le document approuvé destiné à la transmission.",endpoint:"/api/revenue-command-center/proposal/documents"},
  transmission:{title:"Préparer la transmission",subtitle:"Sélectionnez le destinataire, le canal et le document approuvé.",endpoint:"/api/revenue-command-center/proposal/transmissions"},
  "send-proposal":{title:"Confirmer l’envoi externe",subtitle:"Enregistrez uniquement un envoi réellement exécuté par le canal autorisé.",endpoint:"/api/revenue-command-center/proposal/commands"},
  response:{title:"Enregistrer la réponse client",subtitle:"Capturez uniquement un événement réellement reçu et son prochain effet.",endpoint:"/api/revenue-command-center/proposal/responses"},
  "revision-request":{title:"Enregistrer une demande de révision",subtitle:"Formalisez les changements demandés et la prochaine responsabilité.",endpoint:"/api/revenue-command-center/proposal/commands"},
  "open-negotiation":{title:"Ouvrir une négociation",subtitle:"Créez la salle de décision liée à la version actuellement discutée.",endpoint:"/api/revenue-command-center/proposal/negotiations"},
  objection:{title:"Enregistrer une objection",subtitle:"Qualifiez sa source, sa gravité et la stratégie de réponse.",endpoint:"/api/revenue-command-center/proposal/objections"},
  "resolve-objection":{title:"Résoudre une objection",subtitle:"Conservez la réponse, l’auteur et le résultat de résolution.",endpoint:"/api/revenue-command-center/proposal/commands"},
  counteroffer:{title:"Enregistrer une contre-offre",subtitle:"Mesurez la demande du client et son effet financier exact.",endpoint:"/api/revenue-command-center/proposal/counteroffers"},
  concession:{title:"Demander une concession",subtitle:"Aucune concession ne doit exister uniquement dans une note ou un message.",endpoint:"/api/revenue-command-center/proposal/concessions"},
  "approve-concession":{title:"Approuver une concession",subtitle:"Autorisez sa valeur, son coût, son expiration et son impact marge.",endpoint:"/api/revenue-command-center/proposal/commands"},
  "reject-concession":{title:"Rejeter une concession",subtitle:"Préservez la position ANGELCARE et documentez le motif.",endpoint:"/api/revenue-command-center/proposal/commands"},
  "negotiation-position":{title:"Enregistrer une position",subtitle:"Figez la position ANGELCARE ou client dans le round actif.",endpoint:"/api/revenue-command-center/proposal/commands"},
