  "approval-history":{title:"Historique des approbations",subtitle:"Consultez les décisions, motifs, auteurs et dates.",endpoint:"",mode:"view"},
  "commercial-audit":{title:"Audit commercial",subtitle:"Consultez les versions, transitions, communications et décisions enregistrées.",endpoint:"",mode:"view"},
